import{_ as i,o as t,c as n,a2 as u}from"./chunks/framework.CqpfiAoK.js";const r=JSON.parse('{"title":"Jedwali la Kujikagua Utofauti wa Mipangilio","description":"","frontmatter":{},"headers":[],"relativePath":"sw/97-设定矛盾自查表.md","filePath":"sw/97-设定矛盾自查表.md"}'),e={name:"sw/97-设定矛盾自查表.md"};function d(o,a,k,h,l,m){return t(),n("div",null,[...a[0]||(a[0]=[u('<h1 id="jedwali-la-kujikagua-utofauti-wa-mipangilio" tabindex="-1">Jedwali la Kujikagua Utofauti wa Mipangilio <a class="header-anchor" href="#jedwali-la-kujikagua-utofauti-wa-mipangilio" aria-label="Permalink to &quot;Jedwali la Kujikagua Utofauti wa Mipangilio&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Kipengele</th><th>Maudhui</th></tr></thead><tbody><tr><td>Nambari ya hati</td><td>97</td></tr><tr><td>Moduli</td><td>Viambatanisho na Vifaa vya Rujia</td></tr><tr><td>Maneno muhimu</td><td>kujikagua utofauti, utendekanaji wa mipangilio, ukaguzi wa kimantiki, udhibiti wa ubora, utunzaji wa mipangilio</td></tr></tbody></table><h2 id="_1-maelezo" tabindex="-1">1. Maelezo <a class="header-anchor" href="#_1-maelezo" aria-label="Permalink to &quot;1. Maelezo&quot;">​</a></h2><p>Jedwali la Kujikagua Utofauti wa Mipangilio ni chombo cha udhibiti wa ubora wa mfumo wa mipangilio wa Ustaarabu wa Usawa wa Nanga, kinachotumika kuchunguza kwa mtaratibu utofauti wa mipangilio unaoweza kuwepo na utofauti wa kimantiki wakati wa uundaji wa mipangilio mpya, marekebisho ya mipangilio ya zamani, na sasisho ya hati. Jedwali hili la kujikagua limeandaliwa kulingana na mipangilio 14 ya msingi na orodha ya ukaguzi wa utendekanaji iliyoanzishwa katika SPEC.md, na inajumuisha moduli zote kama vile mtazamo wa dunia, mfumo wa u cultivating, mifumo ya kijamii, mfumo wa sheria, umbo la maisha, mfumo wa teknolojia, enzi za kihistoria, na mwingiliano kati ya usawa. Mipangilio yoyote mpya au maudhui ya marekebisho lazima yapite katika vipengele vyote vya ukaguzi vya jedwali hili la kujikagua kabla ya kuingizwa rasmi katika mfumo wa mipangilio.</p><h2 id="_2-ukaguzi-wa-utendekanaji-wa-mipangilio-ya-msingi" tabindex="-1">2. Ukaguzi wa Utendekanaji wa Mipangilio ya Msingi <a class="header-anchor" href="#_2-ukaguzi-wa-utendekanaji-wa-mipangilio-ya-msingi" aria-label="Permalink to &quot;2. Ukaguzi wa Utendekanaji wa Mipangilio ya Msingi&quot;">​</a></h2><h3 id="_2-1-jina-la-ulimwengu-na-dhana-za-msingi" tabindex="-1">2.1 Jina la Ulimwengu na Dhana za Msingi <a class="header-anchor" href="#_2-1-jina-la-ulimwengu-na-dhana-za-msingi" aria-label="Permalink to &quot;2.1 Jina la Ulimwengu na Dhana za Msingi&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Kipengele cha ukaguzi</th><th>Maudhui ya ukaguzi</th><th>Kigezo cha kupita</th><th>Tatizo la kawaida</th></tr></thead><tbody><tr><td>C01</td><td>Je, jina la ulimwengu limeunganishwa</td><td>Tumia &quot;Wan Ling Heng Mao Ben Yuan Zhou&quot; au kifupisho &quot;Hengyuanzhou&quot; kwa umoja katika nakala nzima, usitumie jina lingine</td><td>Mchanganyiko wa majina yasiyo ya kiwango kama vile &quot;ulimwengu&quot;, &quot;ulimwengu wa maelfu&quot;, &quot;mbingu na ulimwengu&quot;</td></tr><tr><td>C02</td><td>Je, ufafanuzi wa nanga unalingana</td><td>Nanga daima inafafanuliwa kama &quot;nodo thabiti katika mtandao wa sheria&quot;, usibadilishe sifa zake za asili</td><td>Kuelezea nanga kama kitu, kiumbe, au mwili wa nguvu</td></tr><tr><td>C03</td><td>Je, dhana ya usawa imeunganishwa</td><td>Usawa daima humaanisha &quot;mageuzi ya pamoja kupitia ushirikiano wa manufaa kwa pande zote kati ya maisha tofauti&quot;, usitoke kwenye msimamo wa kupinga ubaozi</td><td>Kuelezea usawa kama kuingiza, kumeza, au kudhibiti</td></tr><tr><td>C04</td><td>Je, msimamo wa msingi unalingana</td><td>Daima fuata kanuni ya &quot;kuzingatia ukweli&quot;, usielezee mipangilio ya ubuni kama ukweli</td><td>Kuchanganya mipaka kati ya ubuni na ukweli</td></tr></tbody></table><h3 id="_2-2-utendekanaji-wa-mfumo-wa-u-cultivating" tabindex="-1">2.2 Utendekanaji wa Mfumo wa U cultivating <a class="header-anchor" href="#_2-2-utendekanaji-wa-mfumo-wa-u-cultivating" aria-label="Permalink to &quot;2.2 Utendekanaji wa Mfumo wa U cultivating&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Kipengele cha ukaguzi</th><th>Maudhui ya ukaguzi</th><th>Kigezo cha kupita</th><th>Tatizo la kawaida</th></tr></thead><tbody><tr><td>C05</td><td>Je, idadi ya jumla ya mifumo inalingana</td><td>Idadi ya jumla ya mifumo ya u cultivating wa asili daima ni seti tatu mia, huongezwi au hupunguzwi</td><td>Kuonekana kwa maneno ya wazi kama vile &quot;zaidi ya seti tatu mia&quot;, &quot;seti mia kadhaa&quot;</td></tr><tr><td>C06</td><td>Je, uainishaji wa mifumo unalingana</td><td>Daima gawanya katika aina sita (tafakari ya asili, mzunguko wa maisha, sheria za nafasi, kuongeza kiwango cha ufahamu, mtandao wa usawa, uhandisi wa matumizi), na kila aina ina seti hamsini</td><td>Kuonekana kwa mbinu zingine za uainishaji au utofauti wa idadi ya aina</td></tr><tr><td>C07</td><td>Je, misingi mitatu ya asili inalingana</td><td>Seti tatu za kwanza daima ni kurudia tafakari (001), mzunguko wa maisha (002), na usimamizi wa sheria za nafasi (003)</td><td>Kubadilisha nambari au jina la seti tatu za kwanza</td></tr><tr><td>C08</td><td>Je, mipangilio ya tunda la Bei Zeng inalingana</td><td>Tunda la Bei Zeng daima ni &quot;buff ya kuanza&quot;, linatoa kuongezeka kwa tafakari kwa mara mia moja, na tayari limetumika kwa teknolojia</td><td>Kuelezea tunda la Bei Zeng kama tunda la asili au lisilo kwa teknolojia</td></tr><tr><td>C09</td><td>Je, mazingira ya u cultivating yanalingana</td><td>Uainishaji wa mazingira ya kila mfumo unalingana na hati 14 &quot;Uainishaji wa Umoja wa Mazingira ya U cultivating&quot;</td><td>Kubuni mwenyewe majina ya mazingira yanayopingana na uainishaji wa umoja</td></tr><tr><td>C10</td><td>Je, msimamo wa kupinga ubaozi unalingana</td><td>Usielezee u cultivating wa aina ya ubaozi kama mfumo wa chanya au unaopokelewa</td><td>Kuteteza au kupambazua u cultivating wa aina ya ubaozi</td></tr></tbody></table><h3 id="_2-3-utendekanaji-wa-kijamii-na-kisheria" tabindex="-1">2.3 Utendekanaji wa Kijamii na Kisheria <a class="header-anchor" href="#_2-3-utendekanaji-wa-kijamii-na-kisheria" aria-label="Permalink to &quot;2.3 Utendekanaji wa Kijamii na Kisheria&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Kipengele cha ukaguzi</th><th>Maudhui ya ukaguzi</th><th>Kigezo cha kupita</th><th>Tatizo la kawaida</th></tr></thead><tbody><tr><td>C11</td><td>Je, uainishaji wa utamaduni unalingana</td><td>Daima ni aina tano za uainishaji (umojaji wa Asia Mashariki, fursa za kimaendeleo za Kaskazini mwa Ulaya, anuwai ya Kaskazini mwa Amerika, kijamii bara la Ulaya, kukabiliana na maendeleo)</td><td>Kuonekana aina ya sita au kubadilisha jina la uainishaji</td></tr><tr><td>C12</td><td>Je, mfumo wa sheria unalingana</td><td>Daima ni katiba + sheria ya kazi + sheria ya kulinda watumiaji + sheria tano za ziada (elimu, afya, makazi, mazingira, kuzuia ushamba)</td><td>Kutosha sheria fulani au kuongeza sheria isiyowekwa</td></tr><tr><td>C13</td><td>Je, muundo wa utawala unalingana</td><td>Daima ni Baraza la Nanga (kuunda sheria) + Kamati ya Utendaji wa Usawa (utawala) + Mahakama ya Usawa (haki) + Kamati ya Ufuatiliaji wa Nanga (ufuatiliaji)</td><td>Kubadilisha majina ya taasisi au mgawanyo wa mamlaka</td></tr><tr><td>C14</td><td>Je, mchakato wa mkataba wa uzalishaji wa pamoja unalingana</td><td>Daima unazingatia &quot;kazi nyingi faida nyingi&quot;, na mgawanyo wa rasilimali unategemea mchango</td><td>Kuelezea mkataba wa uzalishaji wa pamoja kwa usawa wa kila mtu au mgawanyo kulingana na mahitaji</td></tr><tr><td>C15</td><td>Je, mkakati wa uanzishaji wa 20% unalingana</td><td>Daima kuanzisha 20% ya viumbe vyote kuwa wenye nguvu za juu za usawa katika hatua ya kwanza</td><td>Kubadilisha uwiano au lengo la uanzishaji</td></tr></tbody></table><h2 id="_3-ukaguzi-wa-utendekanaji-wa-kimantiki-kati-ya-moduli" tabindex="-1">3. Ukaguzi wa Utendekanaji wa Kimantiki Kati ya Moduli <a class="header-anchor" href="#_3-ukaguzi-wa-utendekanaji-wa-kimantiki-kati-ya-moduli" aria-label="Permalink to &quot;3. Ukaguzi wa Utendekanaji wa Kimantiki Kati ya Moduli&quot;">​</a></h2><h3 id="_3-1-utendekanaji-wa-mstari-wa-wakati" tabindex="-1">3.1 Utendekanaji wa Mstari wa Wakati <a class="header-anchor" href="#_3-1-utendekanaji-wa-mstari-wa-wakati" aria-label="Permalink to &quot;3.1 Utendekanaji wa Mstari wa Wakati&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Kipengele cha ukaguzi</th><th>Maudhui ya ukaguzi</th><th>Kigezo cha kupita</th><th>Tatizo la kawaida</th></tr></thead><tbody><tr><td>L01</td><td>Je, wakati wa matukio ya kihistoria unalingana</td><td>Wakati wa matukio yote ya kihistoria unalingana na hati 93 &quot;Muhtasari wa Kronikali&quot; na hati 70-79</td><td>Tukio lile lile lina wakati tofauti katika hati tofauti</td></tr><tr><td>L02</td><td>Je, uainishaji wa enzi unalingana</td><td>Majina ya enzi na wakati wa kuanza na kumaliza unalingana na hati 70 &quot;Jedwali la Jumla la Uainishaji wa Enzi&quot;</td><td>Kuonekana enzi isiyowekwa au kubadilisha mipaka ya enzi</td></tr><tr><td>L03</td><td>Je, enzi ya watu inalingana</td><td>Enzi ya shughuli za watu muhimu inalingana na hati 95 &quot;Watu na Mashirika Muhimu&quot;</td><td>Mtu anaonekana katika enzi ambayo hakuwepo</td></tr><tr><td>L04</td><td>Je, wakati wa kuonekana kwa teknolojia unalingana</td><td>Wakati wa uvumbuzi na ukomavu wa kila teknolojia unalingana na kronikali</td><td>Teknolojia fulani inatumika katika enzi kabla ya uvumbuzi wake</td></tr></tbody></table><h3 id="_3-2-utendekanaji-wa-mfumo-wa-teknolojia" tabindex="-1">3.2 Utendekanaji wa Mfumo wa Teknolojia <a class="header-anchor" href="#_3-2-utendekanaji-wa-mfumo-wa-teknolojia" aria-label="Permalink to &quot;3.2 Utendekanaji wa Mfumo wa Teknolojia&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Kipengele cha ukaguzi</th><th>Maudhui ya ukaguzi</th><th>Kigezo cha kupita</th><th>Tatizo la kawaida</th></tr></thead><tbody><tr><td>T01</td><td>Je, teknolojia ya kioo cha nakala inalingana</td><td>Kioo cha nakala daima ni &quot;kifaa cha nakala cha 1:1 ambacho hakugusi kitu cha asili&quot;, na mchakato wa kunakala hauingiliani</td><td>Kuelezea kioo cha nakala kama chenye uwezo wa kubadilisha kitu cha asili au kinahitaji kugusa kitu cha asili</td></tr><tr><td>T02</td><td>Je, nafasi iliyotengwa inalingana</td><td>Nafasi iliyotengwa daima ni &quot;nafasi ya kujitegemea iliyotengwa kabisa kutoka nje kwa ukuta wa sheria&quot;</td><td>Kuelezea nafasi iliyotengwa kama chumba cha kawaida au nafasi ya virtual</td></tr><tr><td>T03</td><td>Je, mahitaji ya u cultivating wa sheria za nafasi yanalingana</td><td>Mahitaji ya u cultivating ya kila teknolojia ya nafasi yanalingana na hati 13 &quot;Maelezo ya Mfumo wa Usimamizi wa Sheria za Nafasi&quot;</td><td>Mtu mwenye u cultivating wa chini anatumia teknolojia inayohitaji u cultivating wa juu</td></tr><tr><td>T04</td><td>Je, kitengo cha nguvu kinalingana</td><td>Upimaji wa nguvu hutumia &quot;kitengo cha kiwango cha nguvu&quot; kwa umoja, usitumie vitengo vingine</td><td>Mchanganyiko wa vitengo vya nguvu visivyo ya kiwango kama vile &quot;jiwe la roho&quot;, &quot;sarafu ya kristali&quot;</td></tr></tbody></table><h3 id="_3-3-utendekanaji-wa-sheria-za-kati-ya-usawa-na-muda" tabindex="-1">3.3 Utendekanaji wa Sheria za Kati ya Usawa na Muda <a class="header-anchor" href="#_3-3-utendekanaji-wa-sheria-za-kati-ya-usawa-na-muda" aria-label="Permalink to &quot;3.3 Utendekanaji wa Sheria za Kati ya Usawa na Muda&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Kipengele cha ukaguzi</th><th>Maudhui ya ukaguzi</th><th>Kigezo cha kupita</th><th>Tatizo la kawaida</th></tr></thead><tbody><tr><td>K01</td><td>Je, &quot;kwanza kuchunguza, kisha kuingilia kwa kikomo&quot; inalingana</td><td>Operesheni zote za kurudia nyuma kwa muda na kati ya usawa lazima zifuate kanuni hii, na hazifai kupitia hatua ya uchunguzi</td><td>Kuelezea operesheni ya kuingilia moja kwa moja bila kuchunguza</td></tr><tr><td>K02</td><td>Je, &quot;kurudisha maarifa tu&quot; inalingana</td><td>Tokeo la kale limefupishwa kwa maarifa na taarifa za abstract, na haifai kurudisha vitu vya kimwili, nguvu, au viumbe hai</td><td>Kuelezea tendo cha kurudisha makumbusho ya kale au sampuli hadi kwenye usawa wa mwenyewe</td></tr><tr><td>K03</td><td>Je, mfumo wa idhini ya safari unalingana</td><td>Safari zote za usawa zinahitaji kupata idhini ya kiwango cha husika, na safari bila idhini inakatazwa</td><td>Kuelezea safari isiyo na idhini kwa hiari ya mtu mwenyewe</td></tr><tr><td>K04</td><td>Je, uainishaji wa paradoksi za muda unalingana</td><td>Paradoksi daima hugawanywa katika aina nne: baba mkubwa, taarifa, kiutambulisho, tukio, na huongezwi au hubadilishwi</td><td>Kuonekana aina ya paradoksi isiyowekwa</td></tr><tr><td>K05</td><td>Je, uainishaji wa usawa unalingana</td><td>Usawa daima hugawanywa katika aina tano (asili ya kimwili, udhihirisho wa nguvu, utawala wa ufahamu, sheria zilizovunjika, jirani la asili)</td><td>Kuonekana mbinu zingine za uainishaji</td></tr></tbody></table><h3 id="_3-4-utendekanaji-wa-maisha-na-makabila" tabindex="-1">3.4 Utendekanaji wa Maisha na Makabila <a class="header-anchor" href="#_3-4-utendekanaji-wa-maisha-na-makabila" aria-label="Permalink to &quot;3.4 Utendekanaji wa Maisha na Makabila&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Kipengele cha ukaguzi</th><th>Maudhui ya ukaguzi</th><th>Kigezo cha kupita</th><th>Tatizo la kawaida</th></tr></thead><tbody><tr><td>S01</td><td>Je, uainishaji wa makabila unalingana</td><td>Makabila daima hugawanywa katika aina nane (umbo la binadamu, umbo la mnyama, umbo la mmea, umbo la kiini, umbo la nguvu, umbo la ufahamu, umbo la mitambo, umbo wa mchanganyiko)</td><td>Kuonekana mbinu zingine za uainishaji</td></tr><tr><td>S02</td><td>Je, utunzaji wa maisha ya ajabu unalingana</td><td>Maisha ya ajabu daima hutunzwa kulingana na aina tatu za mchakato wa usimamizi wa kiwango</td><td>Kuelezea utunzaji wa hiari bila mchakato</td></tr><tr><td>S03</td><td>Je, utunzaji wa mwili wa uingizwaji wa giza unalingana</td><td>Mwili wa uingizwaji wa giza daima hutunzwa kulingana na maadili ya roho mbili na kanuni za utunzaji za matawi manne</td><td>Kuelezea tendo la kufuta moja kwa moja roho moja</td></tr><tr><td>S04</td><td>Je, usawa wa makabila yote unalingana</td><td>Makabila yote yenye akili yalingana sawa mbele ya sheria, na haifai kuwa na mipangilio ya ubaguzi wa kabila</td><td>Kuelezea kabila fulani kama cha chini cha asili au cha kufaa kutumwa kama mtumwa</td></tr></tbody></table><h2 id="_4-ukaguzi-wa-muundo-wa-hati-na-kanuni" tabindex="-1">4. Ukaguzi wa Muundo wa Hati na Kanuni <a class="header-anchor" href="#_4-ukaguzi-wa-muundo-wa-hati-na-kanuni" aria-label="Permalink to &quot;4. Ukaguzi wa Muundo wa Hati na Kanuni&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Kipengele cha ukaguzi</th><th>Maudhui ya ukaguzi</th><th>Kigezo cha kupita</th><th>Tatizo la kawaida</th></tr></thead><tbody><tr><td>F01</td><td>Je, muundo wa jina la faili ni sahihi</td><td>Muundo wa jina la faili ni &quot;XX-kichwa cha habari cha hati.md&quot;, XX ni nambari ya tarakimu mbili</td><td>Nambari haipo, kichwa cha habari kina nafasi, upanuzi wa faili ni mbaya</td></tr><tr><td>F02</td><td>Je, kizuizi cha taarifa cha hati kimekamili</td><td>Mwanzo una jedwali la taarifa lenye nambari, moduli, na maneno muhimu (3-5)</td><td>Kizuizi cha taarifa kimepotea au uwanja haujakamilika</td></tr><tr><td>F03</td><td>Je, idadi ya vichwa vya ngazi ya pili inafikia kiwango</td><td>Maudhui ya msingi yana angalau 3 sura zenye vichwa vya ngazi ya pili</td><td>Chini ya 3 vichwa vya ngazi ya pili</td></tr><tr><td>F04</td><td>Je, vipengele vya muundo vimetumika</td><td>Tumia vipengele vya muundo kama vile orodha, jedwali ili kuboresha uwezo wa kusoma</td><td>Tu aya ya maandishi yaliyosafishwa, hakuna orodha au jedwali</td></tr><tr><td>F05</td><td>Je, hitimisho lipo</td><td>Mwisho una aya ya &quot;hitimisho&quot;</td><td>Hitimisho haipo</td></tr><tr><td>F06</td><td>Je, hati zinazohusiana zipo</td><td>Orodhesha 2-3 nambari na majina ya hati zinazohusiana mwishoni</td><td>Hati zinazohusiana zimepotea au hati zinazohusiana hazipo</td></tr><tr><td>F07</td><td>Je, idadi ya maneno inafikia kiwango</td><td>Maudhui ya msingi si chini ya maneno 800 (bila kichwa cha habari na taarifa za meta)</td><td>Maudhui ya msingi ni chini ya maneno 800</td></tr><tr><td>F08</td><td>Je, matumizi ya masharti yameunganishwa</td><td>Tumia masharti ya kiwango kama vile &quot;Hengyuanzhou&quot;, &quot;nanga&quot;, &quot;usawa&quot;</td><td>Masharti hayalingani au matumizi ya maneno yasiyo ya kiwango</td></tr><tr><td>F09</td><td>Je, mtindo wa kuandika unafaa</td><td>Mtindo wa hati ya mipangilio wenye uzito na mtaratibu, hakuna usemi wa kinyume</td><td>Kuonekana kwa usemi wa kinyume, wa hiari</td></tr><tr><td>F10</td><td>Je, nambari inalingana na orodha</td><td>Nambari na kichwa cha habari cha hati linalingana na orodha kamili ya hati 100 katika SPEC.md</td><td>Nambari au kichwa cha habari hakilingani na orodha</td></tr></tbody></table><h2 id="_5-mchakato-wa-kujikagua-na-mbinu-ya-matumizi" tabindex="-1">5. Mchakato wa Kujikagua na Mbinu ya Matumizi <a class="header-anchor" href="#_5-mchakato-wa-kujikagua-na-mbinu-ya-matumizi" aria-label="Permalink to &quot;5. Mchakato wa Kujikagua na Mbinu ya Matumizi&quot;">​</a></h2><h3 id="_5-1-mchakato-wa-kujikagua-kwa-uundaji-wa-mipangilio-mpya" tabindex="-1">5.1 Mchakato wa Kujikagua kwa Uundaji wa Mipangilio Mpya <a class="header-anchor" href="#_5-1-mchakato-wa-kujikagua-kwa-uundaji-wa-mipangilio-mpya" aria-label="Permalink to &quot;5.1 Mchakato wa Kujikagua kwa Uundaji wa Mipangilio Mpya&quot;">​</a></h3><ol><li><strong>Kujikagua awali</strong>: Baada ya kukamilisha uundaji, muumbi anagundua kila kipengele kulingana na jedwali hili la kujikagua, na kuashiria vipengele vilivyo na tatizo.</li><li><strong>Marekebisho na ukamilisho</strong>: Fanya marekebisho kwa vipengele vilivyokuwa na tatizo vilivyokuwa alama, na hakikisha kwamba zote zinapita.</li><li><strong>Ukaguzi wa kushirikiana</strong>: Wasilisha kwa muumbi mwingine wa mipangilio kwa ajili ya ukaguzi wa kushirikiana, na kuzingatia hasa ukaguzi wa utendekanaji kati ya moduli.</li><li><strong>Uidhinishaji wa kamati</strong>: Mabadiliko muhimu ya mipangilio lazima yawasilishwe kwa Kamati ya Utunzaji wa Mipangilio kwa ajili ya uidhinishaji.</li><li><strong>Uhifadhi wa kumbukumbu na sasisho</strong>: Baada ya kupitia katika ukaguzi wote, ingizwa rasmi katika mfumo wa mipangilio na sasisha hati za fahirisi zinazohusiana.</li></ol><h3 id="_5-2-mchakato-wa-kujikagua-kwa-marekebisho-ya-mipangilio-ya-zamani" tabindex="-1">5.2 Mchakato wa Kujikagua kwa Marekebisho ya Mipangilio ya Zamani <a class="header-anchor" href="#_5-2-mchakato-wa-kujikagua-kwa-marekebisho-ya-mipangilio-ya-zamani" aria-label="Permalink to &quot;5.2 Mchakato wa Kujikagua kwa Marekebisho ya Mipangilio ya Zamani&quot;">​</a></h3><ol><li><strong>Tathmini ya athari</strong>: Tathmini hati zingine na moduli za mipangilio ambazo zinaweza kuathiriwa na maudhui ya marekebisho.</li><li><strong>Ukaguzi unaohusiana</strong>: Fanya ukaguzi wa utendekanaji kwa hati zote zinazohusiana zilizoathiriwa.</li><li><strong>Marekebisho ya pamoja</strong>: Fanya marekebisho ya pamoja kwa maudhui yaliyoathiriwa katika hati zinazohusiana.</li><li><strong>Rekodi ya toleo</strong>: Rekodi maudhui ya marekebisho na nambari ya toleo katika hati 99 &quot;Toleo na Maelezo ya Utunzaji wa Hati&quot;.</li><li><strong>Tangenjwa na taarifa</strong>: Marekebisho muhimu lazima yatangaze tangenjwa ya mabadiliko kwa watumiaji wote wa mipangilio.</li></ol><h3 id="_5-3-kujikagua-kwa-ujumla-kwa-mara-kwa-mara" tabindex="-1">5.3 Kujikagua kwa Ujumla kwa Mara kwa Mara <a class="header-anchor" href="#_5-3-kujikagua-kwa-ujumla-kwa-mara-kwa-mara" aria-label="Permalink to &quot;5.3 Kujikagua kwa Ujumla kwa Mara kwa Mara&quot;">​</a></h3><p>Kamati ya Utunzaji wa Mipangilio hufanya kujikagua kwa ujumla wa utendekanaji wa mipangilio mara moja kwa kila robo, na hufanya ukaguzi wa mtaratibu kwa hati zote 100 ili kuchunguza utofauti wa mipangilio unaoweza kuwepo na utofauti wa kimantiki. Matokeo ya kujikagua huundwa kama &quot;Ripoti ya Utendekanaji wa Mipangilio ya Robo&quot;, na inafunuliwa kwa watumiaji wote wa mipangilio.</p><h2 id="hitimisho" tabindex="-1">Hitimisho <a class="header-anchor" href="#hitimisho" aria-label="Permalink to &quot;Hitimisho&quot;">​</a></h2><p>Jedwali la Kujikagua Utofauti wa Mipangilio ni &quot;katiba ya ubora&quot; ya mfumo wa mipangilio wa Ustaarabu wa Usawa wa Nanga. Kupitia vipengele vya ukaguzi vilivyo na mtaratibu na umbo la orodha, inahakikisha kwamba mfumo wa mipangilio hudumisha utendekanaji wa kimantiki na umoja wa masharti wakati wa upanuzi na marekebisho yanayoendelea. Kitu ambacho mfumo mkubwa wa mipangilio unaouogopa zaidi sio maudhui ambayo hayatoshi kuwa tajiri, bali utofauti wa ndani unaokua na utofauti kati ya awali na baadaye. Uwepo wa jedwali hili la kujikagua ni ili mfumo wa mipangilio wa Ustaarabu wa Usawa wa Nanga, wakati anadumisha ufunguo na uwezo wa ukuaji, daima awe na msingi thabiti wa utendekanaji.</p><h2 id="hati-zinazohusiana" tabindex="-1">Hati zinazohusiana <a class="header-anchor" href="#hati-zinazohusiana" aria-label="Permalink to &quot;Hati zinazohusiana&quot;">​</a></h2><ul><li>99-Toleo na Maelezo ya Utunzaji wa Hati</li><li>90-Kamusi ya Masharti</li><li>00-Muhtasari wa Ulimwengu wa Hengyuanzhou</li></ul>',33)])])}const g=i(e,[["render",d]]);export{r as __pageData,g as default};
